class OrderServiceDelegate {
  private cachedService: OrderService | null = null;

  private async lookup(): Promise<OrderService> {
    if (!this.cachedService) {
      this.cachedService = await jndiLookupWithRetry("OrderService", 3);
    }
    return this.cachedService;
  }

  async placeOrder(cart: Cart): Promise<void> {
    const service = await this.lookup();
    return service.placeOrder(cart);
  }
}

// UI code never touches JNDI, retries, or remote exceptions
const delegate = new OrderServiceDelegate();
button.onClick = () => delegate.placeOrder(cart);
